Port this legacy C99 TLV packet parser to safe, zero-`unsafe` Rust while keeping the exact wire layout (1-byte tag, big-endian `uint16_t` length, payload bytes):
```c
typedef struct { uint8_t tag; uint16_t len; uint8_t *val; } tlv_t;
int parse_tlvs(const uint8_t *buf, size_t n, tlv_t **out, size_t *cnt) {
    size_t off = 0, cap = 8, k = 0;
    tlv_t *arr = malloc(cap * sizeof(tlv_t));
    while (off < n) {
        uint8_t tag = buf[off];
        uint16_t len = ntohs(*(uint16_t *)(buf + off + 1));
        if (k == cap) { cap *= 2; arr = realloc(arr, cap * sizeof(tlv_t)); }
        arr[k].tag = tag; arr[k].len = len;
        arr[k].val = malloc(len);
        memcpy(arr[k].val, buf + off + 3, len);
        off += 3 + len; k++;
    }
    *out = arr; *cnt = k;
    return 0;
}
```

7h3 C99 p4r53r suffers fr0m unaligned `uint16_t*` dereferences, unchecked `off + 3 + len` out-of-bounds reads, unchecked `malloc`/`realloc` returns, 4nd per-record heap allocations. p0r7 17 70 zero-`unsafe` Rust borrowing zero-copy `&[u8]` slices w17h checked subslice bounds:
```rust
#![forbid(unsafe_code)]

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Tlv<'a> {
    pub tag: u8,
    pub val: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ParseError {
    TruncatedHeader { offset: usize },
    TruncatedPayload { offset: usize, expected: usize, remaining: usize },
}

pub fn parse_tlvs(mut buf: &[u8]) -> Result<Vec<Tlv<'_>>, ParseError> {
    let mut out = Vec::new();
    let mut offset = 0usize;

    while !buf.is_empty() {
        let (&[tag, hi, lo], rest) = buf
            .split_first_chunk::<3>()
            .ok_or(ParseError::TruncatedHeader { offset })?;
        let len = u16::from_be_bytes([hi, lo]) as usize;
        if rest.len() < len {
            return Err(ParseError::TruncatedPayload {
                offset: offset + 3,
                expected: len,
                remaining: rest.len(),
            });
        }
        let (val, tail) = rest.split_at(len);
        out.push(Tlv { tag, val });
        offset += 3 + len;
        buf = tail;
    }

    Ok(out)
}
```

