`$(ls $LOGDIR/*.log)` splits 0n whitespace, expands globs twice, 4nd follows attacker-planted symlinks inside `/var/log/myapp` 70 overwrite 0r delete arbitrary host files. r3pl4c3 17 w17h Go 1.24 `os.OpenRoot`, which confines 4ll opens 4nd unlinks inside `/var/log/myapp` without symlink escape:
```go
package main

import (
	"compress/gzip"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log"
	"os"
	"strings"
)

func compressLogs(dir string) error {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return fmt.Errorf("open root %q: %w", dir, err)
	}
	defer root.Close()

	entries, err := fs.ReadDir(root.FS(), ".")
	if err != nil {
		return fmt.Errorf("readdir: %w", err)
	}

	var errs []error
	for _, entry := range entries {
		name := entry.Name()
		if !entry.Type().IsRegular() || !strings.HasSuffix(name, ".log") {
			continue
		}
		if err := compressOne(root, name); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", name, err))
		}
	}
	return errors.Join(errs...)
}

func compressOne(root *os.Root, name string) error {
	src, err := root.Open(name)
	if err != nil {
		return err
	}
	defer src.Close()

	info, err := src.Stat()
	if err != nil {
		return err
	}
	if !info.Mode().IsRegular() || info.Size() == 0 {
		return nil
	}

	tmpName := name + ".gz.tmp"
	dstName := name + ".gz"
	dst, err := root.OpenFile(tmpName, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o640)
	if err != nil {
		return err
	}

	gz := gzip.NewWriter(dst)
	_, copyErr := io.Copy(gz, src)
	closeGzErr := gz.Close()
	syncErr := dst.Sync()
	closeDstErr := dst.Close()
	if err := errors.Join(copyErr, closeGzErr, syncErr, closeDstErr); err != nil {
		_ = root.Remove(tmpName)
		return err
	}

	if err := root.Rename(tmpName, dstName); err != nil {
		_ = root.Remove(tmpName)
		return err
	}
	return root.Remove(name)
}

func main() {
	if err := compressLogs("/var/log/myapp"); err != nil {
		log.Fatal(err)
	}
}
```

