typedef struct { char key[32]; char val[128]; } kv_t;
int parse_cfg_line(char *line, kv_t *out) {
    char *hash = strchr(line, '#');
    if (hash) *hash = '\0';
    char *k = strtok(line, "=");
    if (!k) return 0; // blank/comment line
