```rust
#![forbid(unsafe_code)]

pub const MAX_KEY_LEN: usize = 31;
pub const MAX_VAL_LEN: usize = 127;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ConfigEntry {
    pub key: String,
    pub val: String,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum ConfigError {
    MissingDelimiter,
    EmptyKey,
    KeyTooLong(usize),
    ValTooLong(usize),
}

pub fn parse_cfg_line(line: &str) -> Result<Option<ConfigEntry>, ConfigError> {
    let without_comment = match line.split_once('#') {
        Some((before, _)) => before,
        None => line,
    };
    let trimmed_line = without_comment.trim_end_matches(['\r', '\n']);
    if trimmed_line.trim().is_empty() {
        return Ok(None);
    }

    let (raw_key, raw_val) = trimmed_line
        .split_once('=')
        .ok_or(ConfigError::MissingDelimiter)?;

    let key = raw_key.trim();
    let val = raw_val.trim();

    if key.is_empty() {
        return Err(ConfigError::EmptyKey);
    }
    if key.len() > MAX_KEY_LEN {
        return Err(ConfigError::KeyTooLong(key.len()));
    }
    if val.len() > MAX_VAL_LEN {
        return Err(ConfigError::ValTooLong(val.len()));
    }

    Ok(Some(ConfigEntry {
        key: key.to_owned(),
        val: val.to_owned(),
    }))
}
```

