struct FlusherCtx { volatile bool running; int interval_ms; void (*flush_fn)(); };
void* worker_loop(void* arg) {
    FlusherCtx* ctx = (FlusherCtx*)arg;
    while (ctx->running) {
        usleep(ctx->interval_ms * 1000);
        ctx->flush_fn();
    }
    return NULL;
}
class MetricsFlusher {
    pthread_t tid_;
    FlusherCtx* ctx_;
public:
    MetricsFlusher(int ms, void (*fn)()) {
        ctx_ = new FlusherCtx{true, ms, fn};
        pthread_create(&tid_, NULL, worker_loop, ctx_);
    }
    ~MetricsFlusher() {
        ctx_->running = false;
        pthread_join(tid_, NULL);
        delete ctx_;
    }
};
```

