#include <chrono>
#include <condition_variable>
#include <functional>
#include <mutex>
#include <stop_token>
#include <thread>
#include <utility>

class MetricsFlusher {
public:
    MetricsFlusher(std::chrono::milliseconds interval, std::move_only_function<void()> flush_fn)
        : worker_([this, interval, fn = std::move(flush_fn)](std::stop_token stoken) mutable {
              std::mutex mtx;
              std::condition_variable_any cv;
              while (!stoken.stop_requested()) {
                  std::unique_lock lock(mtx);
                  if (cv.wait_for(lock, stoken, interval, [&stoken] { return stoken.stop_requested(); })) {
                      break;
                  }
                  lock.unlock();
                  fn();
              }
          }) {}

    MetricsFlusher(const MetricsFlusher&) = delete;
    MetricsFlusher& operator=(const MetricsFlusher&) = delete;

private:
    std::jthread worker_;
};
```

