import pickle, time

def load_session(redis_client, sid):
    raw = redis_client.get("sess:" + sid)
    if not raw:
        return None
    sess = pickle.loads(raw)
    if sess.get("exp", 0) < time.time():
        redis_client.delete("sess:" + sid)
        return None
    return sess

def save_session(redis_client, sid, user_id, roles, ttl=3600):
    payload = {"user_id": user_id, "roles": roles, "exp": int(time.time()) + ttl}
    redis_client.setex("sess:" + sid, ttl, pickle.dumps(payload))
```

