```go
package audit

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/jmoiron/sqlx"
)

type AuditEntry struct {
	ID        int64     `db:"id"`
	Actor     string    `db:"actor"`
	Action    string    `db:"action"`
	CreatedAt time.Time `db:"created_at"`
}

var allowedOrderClauses = map[string]string{
	"created_at_desc": "created_at DESC",
	"created_at_asc":  "created_at ASC",
	"id_desc":         "id DESC",
	"actor_asc":       "actor ASC, id DESC",
}

func QueryAuditLogs(
	ctx context.Context,
	db *sqlx.DB,
	orgID int64,
	actions []string,
	actor string,
	orderKey string,
) ([]AuditEntry, error) {
	if len(actions) == 0 {
		return []AuditEntry{}, nil
	}
	if orderKey == "" {
		orderKey = "created_at_desc"
	}
	orderClause, ok := allowedOrderClauses[orderKey]
	if !ok {
		return nil, errors.New("unsupported order clause")
	}

	base := "SELECT id, actor, action, created_at FROM audit_logs WHERE org_id = ? AND action IN (?)"
	args := []any{orgID, actions}
	if actor != "" {
		base += " AND actor = ?"
		args = append(args, actor)
	}
	base += " ORDER BY " + orderClause + " LIMIT 500"

	expandedQuery, expandedArgs, err := sqlx.In(base, args...)
	if err != nil {
		return nil, fmt.Errorf("expand IN parameters: %w", err)
	}
	expandedQuery = db.Rebind(expandedQuery)

	var out []AuditEntry
	if err := db.SelectContext(ctx, &out, expandedQuery, expandedArgs...); err != nil {
		return nil, err
	}
	return out, nil
}
```

