```go
package main

import (
	"errors"
	"flag"
	"fmt"
	"io/fs"
	"log"
	"os"
	"time"
)

func pruneExpiredUploads(uploadDir string, maxAge time.Duration, now time.Time) (int, error) {
	if maxAge <= 0 {
		return 0, errors.New("maxAge must be positive")
	}
	root, err := os.OpenRoot(uploadDir)
	if err != nil {
		return 0, fmt.Errorf("open root: %w", err)
	}
	defer root.Close()

	cutoff := now.Add(-maxAge)
	removed := 0
	var walkErrs []error

	err = fs.WalkDir(root.FS(), ".", func(relPath string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			walkErrs = append(walkErrs, walkErr)
			return nil
		}
		if relPath == "." || !d.Type().IsRegular() {
			return nil
		}
		info, err := d.Info()
		if err != nil {
			walkErrs = append(walkErrs, err)
			return nil
		}
		if info.ModTime().Before(cutoff) {
			if err := root.Remove(relPath); err != nil && !errors.Is(err, fs.ErrNotExist) {
				walkErrs = append(walkErrs, fmt.Errorf("remove %s: %w", relPath, err))
				return nil
			}
			removed++
		}
		return nil
	})
	if err != nil {
		walkErrs = append(walkErrs, err)
	}
	return removed, errors.Join(walkErrs...)
}

func main() {
	dir := flag.String("dir", "/srv/uploads", "upload root directory")
	days := flag.Int("days", 7, "delete regular files older than N days")
	flag.Parse()

	n, err := pruneExpiredUploads(*dir, time.Duration(*days)*24*time.Hour, time.Now())
	if err != nil {
		log.Fatalf("prune completed with errors (removed=%d): %v", n, err)
	}
	log.Printf("removed %d expired files", n)
}
```

