pub const MAX_DNS_NAME_LEN: usize = 253;
pub const MAX_LABEL_LEN: usize = 63;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum DnsNameError {
    OutOfBounds,
    InvalidCompressionFlags(u8),
    PointerCycleOrLimit,
    LabelTooLong(usize),
    NameTooLong,
    InvalidLabelAscii,
}

pub fn decode_qname(pkt: &[u8], start_off: usize) -> Result<(String, usize), DnsNameError> {
