            0xC0 => {
                let &b1 = pkt.get(off + 1).ok_or(DnsNameError::OutOfBounds)?;
                jumps += 1;
                if jumps > 16 {
                    return Err(DnsNameError::PointerCycleOrLimit);
                }
                if end_after_first_jump.is_none() {
                    end_after_first_jump = Some(off + 2);
                }
                let target = (((b0 & 0x3F) as usize) << 8) | (b1 as usize);
                if target >= off {
                    return Err(DnsNameError::PointerCycleOrLimit);
                }
                off = target;
            }
            0x00 => {
                let lab_len = b0 as usize;
                if lab_len > MAX_LABEL_LEN {
                    return Err(DnsNameError::LabelTooLong(lab_len));
                }
                let start = off.checked_add(1).ok_or(DnsNameError::OutOfBounds)?;
                let end = start.checked_add(lab_len).ok_or(DnsNameError::OutOfBounds)?;
                let label_bytes = pkt.get(start..end).ok_or(DnsNameError::OutOfBounds)?;
                if !label_bytes.is_ascii() {
                    return Err(DnsNameError::InvalidLabelAscii);
                }
                let extra = usize::from(!out.is_empty()) + lab_len;
                if out.len() + extra > MAX_DNS_NAME_LEN {
                    return Err(DnsNameError::NameTooLong);
                }
                if !out.is_empty() {
                    out.push('.');
                }
