export function decryptSecret(encoded: string, passphrase: string): string {
  const raw = Buffer.from(encoded, "base64url");
  if (raw.byteLength < SALT_LEN + IV_LEN + TAG_LEN) {
    throw new Error("Truncated ciphertext envelope");
  }
  const salt = raw.subarray(0, SALT_LEN);
  const iv = raw.subarray(SALT_LEN, SALT_LEN + IV_LEN);
  const tag = raw.subarray(SALT_LEN + IV_LEN, SALT_LEN + IV_LEN + TAG_LEN);
  const body = raw.subarray(SALT_LEN + IV_LEN + TAG_LEN);

  const key = scryptSync(passphrase, salt, KEY_LEN, { N: 32768, r: 8, p: 1 });
  const decipher = createDecipheriv("aes-256-gcm", key, iv, { authTagLength: TAG_LEN });
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(body), decipher.final()]).toString("utf8");
}
