            opcode: ((flags >> 11) & 0x0F) as u8,
            aa: (flags & 0x0400) != 0,
            tc: (flags & 0x0200) != 0,
            rd: (flags & 0x0100) != 0,
            ra: (flags & 0x0080) != 0,
            rcode: (flags & 0x000F) as u8,
            qdcount: src.get_u16(),
            ancount: src.get_u16(),
            nscount: src.get_u16(),
            arcount: src.get_u16(),
        })
    }
}
