  const out: SafeDict = Object.create(null) as SafeDict;

  for (const src of [base, patch]) {
    for (const key of Object.keys(src)) {
      if (FORBIDDEN_KEYS.has(key) || !Object.hasOwn(src, key)) {
        continue;
      }
      const incoming = src[key];
      const existing = out[key];
      if (isPlainObject(existing) && isPlainObject(incoming)) {
        out[key] = safeDeepMerge(existing, incoming, depth + 1);
      } else if (isPlainObject(incoming)) {
        out[key] = safeDeepMerge(Object.create(null) as SafeDict, incoming, depth + 1);
      } else {
        out[key] = incoming;
      }
    }
  }
  return out;
}
