use std::collections::BTreeMap;
use std::net::Ipv4Addr;
use std::sync::{Arc, RwLock};

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum FibError {
    InvalidPrefixLen(u8),
    LockPoisoned,
}

#[derive(Clone, Default)]
pub struct FibTable {
    routes: Arc<RwLock<BTreeMap<(Ipv4Addr, u8), Ipv4Addr>>>,
}

impl FibTable {
    pub fn insert(&self, prefix: Ipv4Addr, plen: u8, nexthop: Ipv4Addr) -> Result<(), FibError> {
        if plen > 32 {
            return Err(FibError::InvalidPrefixLen(plen));
        }
        let mask = if plen == 0 { 0 } else { (!0u32) << (32 - plen) };
        let canonical = Ipv4Addr::from(u32::from(prefix) & mask);

        let mut writer = self.routes.write().map_err(|_| FibError::LockPoisoned)?;
        writer.insert((canonical, plen), nexthop);
        Ok(())
    }

