const ENVELOPE_VERSION = 1;
const GCM_IV_LEN = 12;
const GCM_TAG_LEN = 16;

export function sealSecret(pubKeyPem: string, plaintext: Buffer, aad: Buffer): Buffer {
  const dek = randomBytes(32);
  const iv = randomBytes(GCM_IV_LEN);

  const cipher = createCipheriv("aes-256-gcm", dek, iv);
  cipher.setAAD(aad);
  const ciphertext = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  const tag = cipher.getAuthTag();

  const wrappedDek = publicEncrypt(
    {
      key: pubKeyPem,
      padding: constants.RSA_PKCS1_OAEP_PADDING,
      oaepHash: "sha256",
    },
    dek,
  );
  dek.fill(0);

  const header = Buffer.alloc(3);
  header.writeUInt8(ENVELOPE_VERSION, 0);
  header.writeUInt16BE(wrappedDek.length, 1);

  return Buffer.concat([header, wrappedDek, iv, tag, ciphertext]);
}

export function openSecret(privKeyPem: string, envelope: Buffer, aad: Buffer): Buffer {
