  const wrappedLen = envelope.readUInt16BE(1);
  const minTotal = 3 + wrappedLen + GCM_IV_LEN + GCM_TAG_LEN;
  if (wrappedLen === 0 || envelope.length < minTotal) {
    throw new Error("Malformed wrapped key length");
