  const wrappedDek = envelope.subarray(offset, offset + wrappedLen);
  offset += wrappedLen;
  const iv = envelope.subarray(offset, offset + GCM_IV_LEN);
  offset += GCM_IV_LEN;
  const tag = envelope.subarray(offset, offset + GCM_TAG_LEN);
  offset += GCM_TAG_LEN;
  const ciphertext = envelope.subarray(offset);

  const dek = privateDecrypt(
    {
      key: privKeyPem,
      padding: constants.RSA_PKCS1_OAEP_PADDING,
      oaepHash: "sha256",
    },
    wrappedDek,
  );
  try {
    const decipher = createDecipheriv("aes-256-gcm", dek, iv);
    decipher.setAAD(aad);
    decipher.setAuthTag(tag);
