use std::net::Ipv4Addr;

pub const NF5_HEADER_LEN: usize = 24;
pub const NF5_RECORD_LEN: usize = 48;
pub const NF5_MAX_RECORDS: usize = 30;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NetflowHeader {
    pub sys_uptime: u32,
    pub unix_secs: u32,
    pub unix_nsecs: u32,
    pub flow_seq: u32,
    pub engine_type: u8,
    pub engine_id: u8,
    pub sampling: u16,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct FlowItem {
    pub src_ip: Ipv4Addr,
    pub dst_ip: Ipv4Addr,
    pub pkts: u32,
    pub octets: u32,
    pub src_port: u16,
    pub dst_port: u16,
    pub proto: u8,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum NetflowError {
    TruncatedHeader,
    UnsupportedVersion(u16),
    InvalidRecordCount(usize),
    PayloadLengthMismatch { expected: usize, actual: usize },
}

fn be_u16(slice: &[u8], off: usize) -> u16 {
    u16::from_be_bytes([slice[off], slice[off + 1]])
}

fn be_u32(slice: &[u8], off: usize) -> u32 {
    u32::from_be_bytes([slice[off], slice[off + 1], slice[off + 2], slice[off + 3]])
}

pub fn parse_nf5(pkt: &[u8]) -> Result<(NetflowHeader, Vec<FlowItem>), NetflowError> {
    if pkt.len() < NF5_HEADER_LEN {
        return Err(NetflowError::TruncatedHeader);
    }
    let (hdr_bytes, body) = pkt.split_at(NF5_HEADER_LEN);

    let version = be_u16(hdr_bytes, 0);
    if version != 5 {
        return Err(NetflowError::UnsupportedVersion(version));
    }

    let count = be_u16(hdr_bytes, 2) as usize;
    if count == 0 || count > NF5_MAX_RECORDS {
        return Err(NetflowError::InvalidRecordCount(count));
    }

    let expected_body = count
        .checked_mul(NF5_RECORD_LEN)
        .ok_or(NetflowError::InvalidRecordCount(count))?;
    if body.len() != expected_body {
        return Err(NetflowError::PayloadLengthMismatch {
            expected: expected_body,
            actual: body.len(),
        });
    }

    let header = NetflowHeader {
        sys_uptime: be_u32(hdr_bytes, 4),
        unix_secs: be_u32(hdr_bytes, 8),
        unix_nsecs: be_u32(hdr_bytes, 12),
        flow_seq: be_u32(hdr_bytes, 16),
        engine_type: hdr_bytes[20],
        engine_id: hdr_bytes[21],
        sampling: be_u16(hdr_bytes, 22),
    };

    let mut items = Vec::with_capacity(count);
    for rec in body.chunks_exact(NF5_RECORD_LEN) {
        items.push(FlowItem {
            src_ip: Ipv4Addr::from(be_u32(rec, 0)),
            dst_ip: Ipv4Addr::from(be_u32(rec, 4)),
            pkts: be_u32(rec, 16),
            octets: be_u32(rec, 20),
            src_port: be_u16(rec, 32),
            dst_port: be_u16(rec, 34),
            proto: rec[38],
        });
    }

    Ok((header, items))
}
