func runExclusiveSync(lockPath, srcDir, destSpec string, timeout time.Duration) error {
	cleanSrc := filepath.Clean(srcDir)
	info, err := os.Stat(cleanSrc)
	if err != nil || !info.IsDir() {
		return fmt.Errorf("invalid source directory %q", cleanSrc)
	}

	lockFile, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o600)
	if err != nil {
		return fmt.Errorf("open lock %q: %w", lockPath, err)
	}
