	srcDir := flag.String("src", "/var/lib/app-data", "source directory")
	dest := flag.String("dest", "backup@10.20.30.40:/srv/backups/", "rsync destination")
	timeout := flag.Duration("timeout", 15*time.Minute, "max sync runtime")
