#[derive(Debug, Clone, PartialEq, Eq)]
pub enum UrlDecodeError {
    InvalidPercentEscape { index: usize },
    NullByteDisallowed { index: usize },
    InvalidUtf8,
}

fn hex_val(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}

pub fn url_decode_form(input: &str) -> Result<String, UrlDecodeError> {
    let bytes = input.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0usize;

    while i < bytes.len() {
        match bytes[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' => {
                let hi = bytes
                    .get(i + 1)
                    .copied()
                    .and_then(hex_val)
                    .ok_or(UrlDecodeError::InvalidPercentEscape { index: i })?;
                let lo = bytes
                    .get(i + 2)
                    .copied()
                    .and_then(hex_val)
                    .ok_or(UrlDecodeError::InvalidPercentEscape { index: i })?;
                let decoded = (hi << 4) | lo;
                if decoded == 0 {
                    return Err(UrlDecodeError::NullByteDisallowed { index: i });
                }
                out.push(decoded);
                i += 3;
            }
            b => {
                out.push(b);
                i += 1;
            }
        }
    }

    String::from_utf8(out).map_err(|_| UrlDecodeError::InvalidUtf8)
}
