func reloadVerifiedDaemon(pidFile, expectedExe string) error {
	wantExe, err := filepath.EvalSymlinks(expectedExe)
	if err != nil {
		return fmt.Errorf("resolve expected binary %q: %w", expectedExe, err)
	}

	raw, err := os.ReadFile(pidFile)
