		return fmt.Errorf("invalid pid in %q", pidFile)
	}

	procExeLink := fmt.Sprintf("/proc/%d/exe", pid)
	gotExe, err := os.Readlink(procExeLink)
	if err != nil {
		return fmt.Errorf("readlink %s: %w", procExeLink, err)
	}
	gotExe = strings.TrimSuffix(gotExe, " (deleted)")
	if gotExe != wantExe {
		return errors.New("pid executable mismatch; refusing to signal")
	}

	return syscall.Kill(pid, syscall.SIGHUP)
}

func main() {
	pidFile := flag.String("pidfile", "/run/collector/collector.pid", "path to daemon PID file")
	exePath := flag.String("exe", "/usr/sbin/collector", "expected daemon binary path")
	flag.Parse()

	if err := reloadVerifiedDaemon(*pidFile, *exePath); err != nil {
