use bytes::Bytes;
use tokio::sync::mpsc;
use tokio::task::JoinSet;

#[derive(Clone)]
pub struct PacketDispatcher {
    tx: mpsc::Sender<Bytes>,
}

impl PacketDispatcher {
    pub fn spawn_pool(capacity: usize, workers: usize) -> (Self, JoinSet<()>) {
        let (tx, rx) = mpsc::channel::<Bytes>(capacity);
        let shared_rx = std::sync::Arc::new(tokio::sync::Mutex::new(rx));
        let mut set = JoinSet::new();

        for worker_id in 0..workers {
            let rx_handle = std::sync::Arc::clone(&shared_rx);
            set.spawn(async move {
                loop {
                    let maybe_pkt = {
                        let mut guard = rx_handle.lock().await;
                        guard.recv().await
                    };
                    match maybe_pkt {
                        Some(pkt) => {
                            tracing::debug!(worker_id, len = pkt.len(), "processed packet");
                        }
                        None => break,
                    }
                }
            });
        }
        (Self { tx }, set)
    }

    pub async fn enqueue(&self, pkt: Bytes) -> Result<(), &'static str> {
        self.tx.send(pkt).await.map_err(|_| "worker pool shut down")
    }
}
