#include <cstddef>
#include <cstdint>
#include <span>
#include <variant>

enum class DerError {
    EmptyInput,
    IndefiniteOrOversizedLength,
    TruncatedLength,
    NonMinimalEncoding,
    TruncatedContent,
};

struct DerContent {
    std::span<const std::byte> body;
    std::span<const std::byte> rest;
};

[[nodiscard]] std::variant<DerContent, DerError> parse_der_definite_body(
    std::span<const std::byte> input
) noexcept {
    if (input.empty()) {
        return DerError::EmptyInput;
    }
    const auto first = std::to_integer<std::uint8_t>(input[0]);
    std::size_t hdr_len = 1;
    std::size_t body_len = 0;

    if ((first & 0x80U) == 0U) {
        body_len = first;
    } else {
        const std::size_t num_octets = first & 0x7FU;
        if (num_octets == 0U || num_octets > 4U) {
            return DerError::IndefiniteOrOversizedLength;
        }
        if (input.size() < 1U + num_octets) {
            return DerError::TruncatedLength;
        }
        if (std::to_integer<std::uint8_t>(input[1]) == 0U) {
            return DerError::NonMinimalEncoding;
        }
        for (std::size_t i = 0; i < num_octets; ++i) {
            body_len = (body_len << 8U) | std::to_integer<std::uint8_t>(input[1U + i]);
        }
        if (body_len < 128U) {
            return DerError::NonMinimalEncoding;
        }
        hdr_len = 1U + num_octets;
    }
    if (input.size() - hdr_len < body_len) {
        return DerError::TruncatedContent;
    }
    return DerContent{
        .body = input.subspan(hdr_len, body_len),
        .rest = input.subspan(hdr_len + body_len),
    };
}
