func fetchExpectedSHA512(ctx context.Context, client *http.Client, url string) (string, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return "", err
	}
	resp, err := client.Do(req)
	if err != nil {
		return "", err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("sum status %d for %s", resp.StatusCode, url)
	}
	raw, err := io.ReadAll(io.LimitReader(resp.Body, 1024))
	if err != nil {
		return "", err
	}
	fields := strings.Fields(string(raw))
	if len(fields) == 0 || len(fields[0]) != 128 {
		return "", fmt.Errorf("malformed sha512 file at %s", url)
	}
	return strings.ToLower(fields[0]), nil
}

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, nil))
	client := &http.Client{Timeout: 45 * time.Second}
	g, ctx := errgroup.WithContext(context.Background())
	g.SetLimit(4)

	for _, tarURL := range os.Args[1:] {
		g.Go(func() error {
			exp, err := fetchExpectedSHA512(ctx, client, tarURL+".sha512")
			if err != nil {
				return err
			}
			req, err := http.NewRequestWithContext(ctx, http.MethodGet, tarURL, nil)
			if err != nil {
				return err
			}
			resp, err := client.Do(req)
			if err != nil {
				return err
			}
			defer resp.Body.Close()
			if resp.StatusCode != http.StatusOK {
				return fmt.Errorf("bundle status %d for %s", resp.StatusCode, tarURL)
			}
			h := sha512.New()
			n, err := io.Copy(h, resp.Body)
			if err != nil {
				return err
			}
			act := hex.EncodeToString(h.Sum(nil))
			if subtle.ConstantTimeCompare([]byte(exp), []byte(act)) != 1 {
				logger.Error("sha512_mismatch", "url", tarURL, "expected", exp, "actual", act)
				return fmt.Errorf("sha512 mismatch on %s", tarURL)
			}
			logger.Info("bundle_verified", "url", tarURL, "bytes", n, "sha512", act)
			return nil
		})
	}
	if err := g.Wait(); err != nil {
		logger.Error("bundle_audit_failed", "err", err)
		os.Exit(1)
	}
}
