use tokio::net::{TcpListener, TcpStream};
use tokio::sync::Semaphore;
use tokio::time::timeout;

pub async fn run_tcp_relay(
    listen_addr: SocketAddr,
    upstream_addr: SocketAddr,
    max_flows: usize,
) -> io::Result<()> {
    let listener = TcpListener::bind(listen_addr).await?;
    let limiter = Arc::new(Semaphore::new(max_flows));

    loop {
        let permit = limiter.clone().acquire_owned().await.expect("limiter active");
        let (mut inbound, _peer) = listener.accept().await?;

        tokio::spawn(async move {
            let _permit = permit;
            let connect_fut = TcpStream::connect(upstream_addr);
            if let Ok(Ok(mut outbound)) = timeout(Duration::from_secs(3), connect_fut).await {
                let _ = inbound.set_nodelay(true);
                let _ = outbound.set_nodelay(true);
                let _ = timeout(
                    Duration::from_secs(60),
                    copy_bidirectional(&mut inbound, &mut outbound),
                )
                .await;
            }
        });
    }
}
```
