  const nonce = buf.subarray(SALT_LEN, SALT_LEN + NONCE_LEN);
  const tag = buf.subarray(SALT_LEN + NONCE_LEN, SALT_LEN + NONCE_LEN + TAG_LEN);
  const ct = buf.subarray(SALT_LEN + NONCE_LEN + TAG_LEN);

