#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TcpOption<'a> {
    pub kind: u8,
    pub data: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TcpOptError {
    TruncatedLength { offset: usize, kind: u8 },
    InvalidOptionLength { offset: usize, kind: u8, len: u8 },
    TruncatedOptionData { offset: usize, kind: u8, len: usize, remaining: usize },
}

pub fn parse_tcp_opts(opts: &[u8]) -> Result<Vec<TcpOption<'_>>, TcpOptError> {
    let mut parsed = Vec::new();
    let mut i = 0usize;

    while i < opts.len() {
        let kind = opts[i];
        match kind {
            0 => break, // End of Option List (EOL)
            1 => {
                i += 1; // No-Operation (NOP)
            }
            _ => {
                let &raw_len = opts
                    .get(i + 1)
                    .ok_or(TcpOptError::TruncatedLength { offset: i, kind })?;
                if raw_len < 2 {
                    return Err(TcpOptError::InvalidOptionLength {
                        offset: i,
                        kind,
                        len: raw_len,
                    });
                }
                let total_len = raw_len as usize;
                let remaining = opts.len() - i;
                if total_len > remaining {
                    return Err(TcpOptError::TruncatedOptionData {
                        offset: i,
                        kind,
                        len: total_len,
                        remaining,
                    });
                }
                let data = &opts[(i + 2)..(i + total_len)];
                parsed.push(TcpOption { kind, data });
                i += total_len;
            }
        }
    }

