package main

import (
	"archive/tar"
	"compress/gzip"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"path/filepath"
)

const (
	maxTotalBytes = 128 << 20 // 128 MiB
	maxFileBytes  = 32 << 20  // 32 MiB
	maxEntries    = 2048
)

func extractBundleSafely(bundlePath, destDir string) error {
	if err := os.MkdirAll(destDir, 0o755); err != nil {
		return err
	}
	root, err := os.OpenRoot(destDir)
	if err != nil {
		return fmt.Errorf("open root %q: %w", destDir, err)
	}
	defer root.Close()

	f, err := os.Open(bundlePath)
	if err != nil {
		return err
	}
	defer f.Close()

	gz, err := gzip.NewReader(f)
	if err != nil {
		return err
	}
	defer gz.Close()

	tr := tar.NewReader(gz)
	var totalWritten int64
	entries := 0

	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		entries++
		if entries > maxEntries {
			return errors.New("archive exceeds maximum entry count")
		}

		rel := filepath.Clean(hdr.Name)
		if rel == "." {
			continue
		}

		switch hdr.Typeflag {
		case tar.TypeDir:
			if err := root.MkdirAll(rel, 0o755); err != nil {
				return err
			}
		case tar.TypeReg:
			if hdr.Size < 0 || hdr.Size > maxFileBytes || totalWritten+hdr.Size > maxTotalBytes {
				return fmt.Errorf("entry %q exceeds size limits", hdr.Name)
			}
			if parent := filepath.Dir(rel); parent != "." {
				if err := root.MkdirAll(parent, 0o755); err != nil {
					return err
				}
			}
			perm := os.FileMode(hdr.Mode) & 0o755
			if perm == 0 {
				perm = 0o644
			}
			out, err := root.OpenFile(rel, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, perm)
			if err != nil {
				return err
			}
			n, copyErr := io.CopyN(out, tr, hdr.Size)
			closeErr := out.Close()
			if err := errors.Join(copyErr, closeErr); err != nil {
				return err
			}
			totalWritten += n
		default:
			return fmt.Errorf("disallowed tar entry type %d for %q", hdr.Typeflag, hdr.Name)
		}
	}
}

func main() {
	if len(os.Args) != 2 {
		log.Fatalf("usage: %s <bundle.tar.gz>", os.Args[0])
	}
	if err := extractBundleSafely(os.Args[1], "/srv/plugins"); err != nil {
		log.Fatal(err)
	}
}
```

