import { z } from "zod";

export interface MetricRow {
  readonly host: string;
  readonly region: string;
  readonly cpuPct: number;
  readonly statusCode: number;
}

const StringFieldSchema = z.enum(["host", "region"]);
const NumberFieldSchema = z.enum(["cpuPct", "statusCode"]);

type FilterNode =
  | { op: "str_eq"; field: "host" | "region"; value: string }
  | { op: "str_in"; field: "host" | "region"; values: string[] }
  | { op: "num_gt"; field: "cpuPct" | "statusCode"; value: number }
  | { op: "num_lt"; field: "cpuPct" | "statusCode"; value: number }
  | { op: "and"; rules: FilterNode[] };

const LeafRuleSchema: z.ZodType<FilterNode> = z.discriminatedUnion("op", [
  z.object({ op: z.literal("str_eq"), field: StringFieldSchema, value: z.string() }).strict(),
  z.object({ op: z.literal("str_in"), field: StringFieldSchema, values: z.array(z.string()).max(50) }).strict(),
  z.object({ op: z.literal("num_gt"), field: NumberFieldSchema, value: z.number().finite() }).strict(),
  z.object({ op: z.literal("num_lt"), field: NumberFieldSchema, value: z.number().finite() }).strict(),
]);

export const FilterNodeSchema: z.ZodType<FilterNode> = z.lazy(() =>
  z.union([
    LeafRuleSchema,
    z.object({ op: z.literal("and"), rules: z.array(FilterNodeSchema).min(1).max(16) }).strict(),
  ]),
);

function evalNode(row: MetricRow, node: FilterNode, depth = 0): boolean {
  if (depth > 8) {
    throw new Error("Filter nesting depth exceeded");
  }
  switch (node.op) {
    case "str_eq":
      return row[node.field] === node.value;
    case "str_in":
      return node.values.includes(row[node.field]);
    case "num_gt":
      return row[node.field] > node.value;
    case "num_lt":
      return row[node.field] < node.value;
    case "and":
      return node.rules.every((child) => evalNode(row, child, depth + 1));
  }
}

export function filterRows(rows: readonly MetricRow[], untrustedFilter: unknown): MetricRow[] {
  if (untrustedFilter === undefined || untrustedFilter === null) {
    return [...rows];
  }
  const ast = FilterNodeSchema.parse(untrustedFilter);
  return rows.filter((r) => evalNode(r, ast));
}
