    scryptCb(
      password.normalize("NFKC"),
      salt,
      SCRYPT_KEYLEN,
      { N: SCRYPT_N, r: SCRYPT_R, p: SCRYPT_P, maxmem: SCRYPT_MAXMEM },
      (err, derivedKey) => (err ? reject(err) : resolve(derivedKey)),
