export async function loginUser(db: AuthUserRepo, email: string, password: string): Promise<boolean> {
  const user = await db.findByEmail(email);
  if (!user) {
    await deriveScrypt(password, Buffer.alloc(16));
    return false;
  }

  const parts = user.passHash.split("$");
  if (parts.length !== 3) {
    return false;
