    const candidate = await deriveScrypt(password, Buffer.from(saltPart, "hex"));
    return expected.length === candidate.length && timingSafeEqual(expected, candidate);
  }

  if (alg === "md5") {
    if (!/^[0-9a-f]{32}$/i.test(digestHex)) {
      return false;
    }
    const expected = Buffer.from(digestHex, "hex");
    const candidate = createHash("md5").update(`${saltPart}:${password}`, "utf8").digest();
    if (expected.length !== candidate.length || !timingSafeEqual(expected, candidate)) {
      return false;
    }
