		return errors.New("policy payload empty or exceeds size cap")
	}
	if !json.Valid(body) {
		return errors.New("downloaded policy is not valid JSON")
	}

	destDir := filepath.Dir(destPath)
	tmp, err := os.CreateTemp(destDir, ".policy.json.tmp.*")
	if err != nil {
