```ts
import type { ZodType } from "zod";

export interface FetchJsonOptions {
  timeoutMs?: number;
  maxBytes?: number;
  headers?: Record<string, string>;
}

async function readBoundedText(resp: Response, maxBytes: number): Promise<string> {
  if (!resp.body) {
    return "";
  }
  const reader = resp.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;

  try {
    while (true) {
      const { done, value } = await reader.read();
      if (done) {
        break;
      }
      total += value.byteLength;
      if (total > maxBytes) {
        await reader.cancel("Response exceeded maxBytes");
        throw new Error(`JSON response exceeded ${maxBytes} bytes`);
      }
      chunks.push(value);
    }
  } finally {
    reader.releaseLock();
  }

  const merged = new Uint8Array(total);
  let offset = 0;
  for (const c of chunks) {
    merged.set(c, offset);
    offset += c.byteLength;
  }
  return new TextDecoder("utf-8", { fatal: true }).decode(merged);
}

export async function getValidatedJson<T>(
  url: string,
  schema: ZodType<T>,
  opts: FetchJsonOptions = {},
): Promise<T> {
  const timeoutMs = opts.timeoutMs ?? 5_000;
  const maxBytes = opts.maxBytes ?? 1_048_576;

  const resp = await fetch(url, {
    method: "GET",
    headers: { Accept: "application/json", ...opts.headers },
    redirect: "error",
    signal: AbortSignal.timeout(timeoutMs),
  });

  if (!resp.ok) {
    throw new Error(`Unexpected HTTP status ${resp.status} from ${url}`);
  }

  const text = await readBoundedText(resp, maxBytes);
  const parsedJson: unknown = JSON.parse(text);
  return schema.parse(parsedJson);
}
