    {
        "created_desc" => "CreatedUtc DESC, Id DESC",
        "created_asc"  => "CreatedUtc ASC, Id ASC",
        "order_number" => "OrderNumber ASC",
        "status"       => "Status ASC, CreatedUtc DESC",
        _ => throw new ArgumentOutOfRangeException(nameof(sortKey), "Unsupported sort column."),
