var posixNameRe = regexp.MustCompile(`^[a-z_][a-z0-9_-]{0,31}$`)

var forbiddenGroups = map[string]bool{
	"root":   true,
	"wheel":  true,
	"sudo":   true,
	"docker": true,
	"shadow": true,
}

func provisionAccount(parent context.Context, username, group string) error {
	if !posixNameRe.MatchString(username) || username == "root" {
		return fmt.Errorf("rejected invalid username %q", username)
	}
	if !posixNameRe.MatchString(group) || forbiddenGroups[group] {
		return fmt.Errorf("rejected invalid or privileged group %q", group)
	}

	ctx, cancel := context.WithTimeout(parent, 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(
		ctx,
		"/usr/sbin/useradd",
		"-m",
		"-s", "/bin/bash",
		"-G", group,
		"--",
		username,
	)
	out, err := cmd.CombinedOutput()
	if err != nil {
		return fmt.Errorf("useradd %s: %w (%s)", username, err, strings.TrimSpace(string(out)))
	}
	return nil
}

func runCSVProvision(csvPath string) error {
	f, err := os.Open(csvPath)
	if err != nil {
		return err
	}
	defer f.Close()

	r := csv.NewReader(f)
	r.FieldsPerRecord = 2
	var errs []error
	lineNo := 0

	for {
		rec, err := r.Read()
		if errors.Is(err, io.EOF) {
			break
		}
		lineNo++
		if err != nil {
			errs = append(errs, fmt.Errorf("line %d: %w", lineNo, err))
			continue
		}
		user := strings.TrimSpace(rec[0])
		grp := strings.TrimSpace(rec[1])
		if lineNo == 1 && user == "user" && grp == "group" {
			continue
		}
		if err := provisionAccount(context.Background(), user, grp); err != nil {
			errs = append(errs, fmt.Errorf("line %d: %w", lineNo, err))
		}
	}
	return errors.Join(errs...)
}

func main() {
	if len(os.Args) != 2 {
		log.Fatalf("usage: %s <users.csv>", os.Args[0])
	}
	if err := runCSVProvision(os.Args[1]); err != nil {
		log.Fatal(err)
	}
}
