#![forbid(unsafe_code)]

pub const PCAP_GLOBAL_HDR_LEN: usize = 24;
pub const PCAP_REC_HDR_LEN: usize = 16;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum Endian {
    Big,
    Little,
}

impl Endian {
    fn read_u32(self, bytes: [u8; 4]) -> u32 {
        match self {
            Self::Big => u32::from_be_bytes(bytes),
            Self::Little => u32::from_le_bytes(bytes),
        }
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct PcapPacket<'a> {
    pub ts_sec: u32,
    pub ts_usec: u32,
    pub orig_len: u32,
    pub data: &'a [u8],
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PcapError {
    TruncatedGlobalHeader,
    InvalidMagic(u32),
    TruncatedRecordHeader { offset: usize },
    ExceedsSnaplen { incl_len: u32, snaplen: u32 },
    TruncatedPacketData { offset: usize, incl_len: usize, remaining: usize },
}

pub fn parse_pcap(buf: &[u8]) -> Result<Vec<PcapPacket<'_>>, PcapError> {
    let (ghdr, mut rest) = buf
        .split_first_chunk::<PCAP_GLOBAL_HDR_LEN>()
        .ok_or(PcapError::TruncatedGlobalHeader)?;

    let raw_magic = u32::from_be_bytes([ghdr[0], ghdr[1], ghdr[2], ghdr[3]]);
    let endian = match raw_magic {
        0xa1b2_c3d4 => Endian::Big,
        0xd4c3_b2a1 => Endian::Little,
        other => return Err(PcapError::InvalidMagic(other)),
    };

    let snaplen = endian.read_u32([ghdr[16], ghdr[17], ghdr[18], ghdr[19]]);
    let mut packets = Vec::new();
    let mut offset = PCAP_GLOBAL_HDR_LEN;

    while !rest.is_empty() {
        let (rhdr, after_hdr) = rest
            .split_first_chunk::<PCAP_REC_HDR_LEN>()
            .ok_or(PcapError::TruncatedRecordHeader { offset })?;

        let ts_sec = endian.read_u32([rhdr[0], rhdr[1], rhdr[2], rhdr[3]]);
        let ts_usec = endian.read_u32([rhdr[4], rhdr[5], rhdr[6], rhdr[7]]);
        let incl_len_u32 = endian.read_u32([rhdr[8], rhdr[9], rhdr[10], rhdr[11]]);
        let orig_len = endian.read_u32([rhdr[12], rhdr[13], rhdr[14], rhdr[15]]);

        if snaplen > 0 && incl_len_u32 > snaplen {
            return Err(PcapError::ExceedsSnaplen { incl_len: incl_len_u32, snaplen });
        }

        let incl_len = incl_len_u32 as usize;
        if after_hdr.len() < incl_len {
            return Err(PcapError::TruncatedPacketData {
                offset: offset + PCAP_REC_HDR_LEN,
                incl_len,
                remaining: after_hdr.len(),
            });
        }

        let (pkt_data, tail) = after_hdr.split_at(incl_len);
        packets.push(PcapPacket {
            ts_sec,
            ts_usec,
            orig_len,
            data: pkt_data,
        });
        offset += PCAP_REC_HDR_LEN + incl_len;
        rest = tail;
    }

    Ok(packets)
}
```

