package main

import (
	"context"
	"crypto/tls"
	"errors"
	"flag"
	"fmt"
	"log"
	"math"
	"net"
	"time"
)

func certDaysRemaining(parent context.Context, host, port string, timeout time.Duration) (int, error) {
	if host == "" {
		return 0, errors.New("host must not be empty")
	}
	ctx, cancel := context.WithTimeout(parent, timeout)
	defer cancel()

	dialer := &tls.Dialer{
		NetDialer: &net.Dialer{Timeout: timeout},
		Config: &tls.Config{
			ServerName: host,
			MinVersion: tls.VersionTLS12,
		},
	}

	conn, err := dialer.DialContext(ctx, "tcp", net.JoinHostPort(host, port))
	if err != nil {
		return 0, fmt.Errorf("tls handshake failed: %w", err)
	}
	defer conn.Close()

	tlsConn, ok := conn.(*tls.Conn)
	if !ok {
		return 0, errors.New("unexpected non-TLS connection")
	}
	certs := tlsConn.ConnectionState().PeerCertificates
	if len(certs) == 0 {
		return 0, errors.New("peer presented zero certificates")
	}

	remaining := time.Until(certs[0].NotAfter)
	days := int(math.Floor(remaining.Hours() / 24.0))
	return days, nil
}

func main() {
	host := flag.String("host", "", "TLS server hostname")
	port := flag.String("port", "443", "TLS server port")
	timeout := flag.Duration("timeout", 5*time.Second, "handshake timeout")
	flag.Parse()

	days, err := certDaysRemaining(context.Background(), *host, *port, *timeout)
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(days)
}
```

