    let mut cur_len = src.read(&mut cur)?;
    let mut seq: u32 = 0;

    loop {
        let mut nxt = vec![0u8; CHUNK_CAP];
        let nxt_len = src.read(&mut nxt)?;
        let is_final = nxt_len == 0;

        let mut nonce_bytes = [0u8; 12];
