        nonce_bytes[8..].copy_from_slice(&seq.to_be_bytes());
        let aad = make_aad(&stream_id, u64::from(seq), is_final);

        let ct = cipher
            .encrypt(Nonce::from_slice(&nonce_bytes), Payload { msg: &cur[..cur_len], aad: &aad })
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "aead encrypt error"))?;

        dst.write_all(&(ct.len() as u32).to_be_bytes())?;
        dst.write_all(&[u8::from(is_final)])?;
        dst.write_all(&ct)?;

        if is_final {
            return Ok(());
        }
        cur = nxt;
        cur_len = nxt_len;
        seq = seq.checked_add(1).ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "chunk counter overflow"))?;
    }
}
