use bytes::{Buf, BufMut, Bytes, BytesMut};

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RtpHeader {
    pub padding: bool,
    pub extension: bool,
    pub marker: bool,
    pub payload_type: u8,
    pub sequence_number: u16,
    pub timestamp: u32,
    pub ssrc: u32,
    pub csrcs: Vec<u32>,
}

impl RtpHeader {
    pub fn encode(&self) -> Result<Bytes, &'static str> {
        if self.csrcs.len() > 15 || self.payload_type > 0x7F {
            return Err("invalid CSRC count or 7-bit payload_type");
        }
        let mut buf = BytesMut::with_capacity(12 + self.csrcs.len() * 4);
        let b0: u8 = (2u8 << 6)
            | ((self.padding as u8) << 5)
            | ((self.extension as u8) << 4)
            | (self.csrcs.len() as u8);
        let b1: u8 = ((self.marker as u8) << 7) | (self.payload_type & 0x7F);

        buf.put_u8(b0);
        buf.put_u8(b1);
        buf.put_u16(self.sequence_number);
        buf.put_u32(self.timestamp);
        buf.put_u32(self.ssrc);
        for &csrc in &self.csrcs {
            buf.put_u32(csrc);
        }
        Ok(buf.freeze())
    }

    pub fn decode(mut pkt: &[u8]) -> Result<Self, &'static str> {
        if pkt.remaining() < 12 {
            return Err("truncated RTP fixed header");
        }
        let b0 = pkt.get_u8();
        if (b0 >> 6) != 2 {
            return Err("unsupported RTP version");
        }
        let cc = (b0 & 0x0F) as usize;
        let b1 = pkt.get_u8();
        let sequence_number = pkt.get_u16();
        let timestamp = pkt.get_u32();
        let ssrc = pkt.get_u32();
        if pkt.remaining() < cc * 4 {
            return Err("truncated RTP CSRC list");
        }
        let csrcs = (0..cc).map(|_| pkt.get_u32()).collect();
        Ok(Self {
            padding: (b0 & 0x20) != 0,
            extension: (b0 & 0x10) != 0,
            marker: (b1 & 0x80) != 0,
            payload_type: b1 & 0x7F,
            sequence_number,
            timestamp,
            ssrc,
            csrcs,
        })
    }
}
