pub struct Socks5Request {
    pub cmd: Socks5Command,
    pub dst_addr: Socks5Addr,
    pub dst_port: u16,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Socks5Error {
    Truncated,
    InvalidVersion(u8),
    NonZeroReserved(u8),
    UnsupportedCommand(u8),
    UnsupportedAddrType(u8),
    InvalidDomain,
    ExtraTrailingBytes,
}

pub fn parse_socks5_req(buf: &[u8]) -> Result<Socks5Request, Socks5Error> {
    let (&[ver, cmd_raw, rsv, atyp], rest) = buf
        .split_first_chunk::<4>()
        .ok_or(Socks5Error::Truncated)?;

    if ver != 0x05 {
        return Err(Socks5Error::InvalidVersion(ver));
    }
    if rsv != 0x00 {
        return Err(Socks5Error::NonZeroReserved(rsv));
    }

    let cmd = match cmd_raw {
        0x01 => Socks5Command::Connect,
        0x02 => Socks5Command::Bind,
        0x03 => Socks5Command::UdpAssociate,
        other => return Err(Socks5Error::UnsupportedCommand(other)),
    };

    let (dst_addr, after_addr) = match atyp {
        0x01 => {
            let (&octets, tail) = rest.split_first_chunk::<4>().ok_or(Socks5Error::Truncated)?;
            (Socks5Addr::Ipv4(Ipv4Addr::from(octets)), tail)
        }
        0x03 => {
            let (&dlen_u8, after_len) = rest.split_first().ok_or(Socks5Error::Truncated)?;
            let dlen = dlen_u8 as usize;
            if dlen == 0 || after_len.len() < dlen {
                return Err(Socks5Error::InvalidDomain);
            }
            let (dom_bytes, tail) = after_len.split_at(dlen);
            let dom = std::str::from_utf8(dom_bytes)
                .ok()
                .filter(|s| s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'.' || b == b'-'))
                .ok_or(Socks5Error::InvalidDomain)?;
            (Socks5Addr::Domain(dom.to_owned()), tail)
        }
        0x04 => {
            let (&octets, tail) = rest.split_first_chunk::<16>().ok_or(Socks5Error::Truncated)?;
            (Socks5Addr::Ipv6(Ipv6Addr::from(octets)), tail)
        }
        other => return Err(Socks5Error::UnsupportedAddrType(other)),
    };

    let (&port_bytes, trailing) = after_addr
        .split_first_chunk::<2>()
        .ok_or(Socks5Error::Truncated)?;
    if !trailing.is_empty() {
        return Err(Socks5Error::ExtraTrailingBytes);
    }

    Ok(Socks5Request {
        cmd,
        dst_addr,
        dst_port: u16::from_be_bytes(port_bytes),
    })
}
```

