var safeStemRe = regexp.MustCompile(`^[a-zA-Z0-9._-]{1,120}$`)

func renderThumbnail(parent context.Context, inRoot, outRoot *os.Root, jpgName string) error {
	stem := strings.TrimSuffix(jpgName, ".jpg")
	if !safeStemRe.MatchString(stem) || strings.HasPrefix(stem, "-") {
		return fmt.Errorf("unsafe filename stem %q", stem)
	}

	srcFile, err := inRoot.Open(jpgName)
	if err != nil {
		return err
	}
	defer srcFile.Close()

	tmpOut := stem + ".png.tmp"
	finalOut := stem + ".png"
	dstFile, err := outRoot.OpenFile(tmpOut, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}

	ctx, cancel := context.WithTimeout(parent, 15*time.Second)
	defer cancel()

	cmd := exec.CommandContext(ctx, "magick", "jpeg:-", "-strip", "-resize", "256x256", "png:-")
	cmd.Stdin = srcFile
	cmd.Stdout = dstFile

	runErr := cmd.Run()
	syncErr := dstFile.Sync()
	closeErr := dstFile.Close()
	if err := errors.Join(runErr, syncErr, closeErr); err != nil {
		_ = outRoot.Remove(tmpOut)
		return err
	}
	return outRoot.Rename(tmpOut, finalOut)
}

func processBatch(inDir, outDir string) error {
	inRoot, err := os.OpenRoot(inDir)
	if err != nil {
		return err
	}
	defer inRoot.Close()

	if err := os.MkdirAll(outDir, 0o755); err != nil {
		return err
	}
	outRoot, err := os.OpenRoot(outDir)
	if err != nil {
		return err
	}
	defer outRoot.Close()

	entries, err := fs.ReadDir(inRoot.FS(), ".")
	if err != nil {
		return err
	}

	var errs []error
	for _, e := range entries {
		if !e.Type().IsRegular() || !strings.HasSuffix(e.Name(), ".jpg") {
			continue
		}
		if err := renderThumbnail(context.Background(), inRoot, outRoot, e.Name()); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", e.Name(), err))
		}
	}
	return errors.Join(errs...)
}

func main() {
	if err := processBatch("/srv/incoming", "/srv/thumbs"); err != nil {
		log.Fatal(err)
	}
}
