        cipher.init(Cipher.ENCRYPT_MODE, key, new GCMParameterSpec(GCM_TAG_BITS, iv));
        cipher.updateAAD(aad);
        byte[] ciphertextAndTag = cipher.doFinal(plaintext);

        return ByteBuffer.allocate(1 + GCM_IV_BYTES + ciphertextAndTag.length)
            .put(VERSION_V2)
            .put(iv)
            .put(ciphertextAndTag)
            .array();
    }

    public static byte[] decryptPayload(SecretKey key, byte[] blob, byte[] aad)
        throws GeneralSecurityException {
        if (aad == null || aad.length == 0) {
            throw new IllegalArgumentException("aad must be non-empty");
        }
