pub enum NetstringError {
    MissingColon,
    EmptyLength,
    LeadingZero,
    InvalidLengthDigit,
    LengthOverflow,
    ExceedsMaxLen { len: usize, max_len: usize },
    TruncatedPayload,
    MissingTrailingComma,
