        return Err(NetstringError::LeadingZero);
    }
    if !len_digits.iter().all(|b| b.is_ascii_digit()) {
        return Err(NetstringError::InvalidLengthDigit);
    }

    let len_str = std::str::from_utf8(len_digits).map_err(|_| NetstringError::InvalidLengthDigit)?;
    let payload_len: usize = len_str.parse().map_err(|_| NetstringError::LengthOverflow)?;
    if payload_len > max_len {
        return Err(NetstringError::ExceedsMaxLen {
            len: payload_len,
            max_len,
        });
    }

    let after_colon = &buf[(colon_pos + 1)..];
    let needed = payload_len
        .checked_add(1)
        .ok_or(NetstringError::LengthOverflow)?;
    if after_colon.len() < needed {
        return Err(NetstringError::TruncatedPayload);
    }

    let (payload, rest_with_comma) = after_colon.split_at(payload_len);
    if rest_with_comma[0] != b',' {
        return Err(NetstringError::MissingTrailingComma);
    }

    Ok((payload, &rest_with_comma[1..]))
}
