import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

public final class NodeInventoryDao {

    private static final Map<String, String> ALLOWED_SORTS = Map.of(
        "hostname", "hostname ASC, id ASC",
        "region", "region ASC, hostname ASC",
        "created_at", "created_at DESC, id DESC"
    );

    private static String escapeLike(String raw) {
        return raw
            .replace("\\", "\\\\")
            .replace("%", "\%")
            .replace("_", "\_");
    }

    public List<String> findHostnames(
        Connection conn,
        long orgId,
        List<String> regions,
        String hostFilter,
        String sortBy
    ) throws SQLException {
        if (regions == null || regions.isEmpty()) {
            return List.of();
        }
        String orderClause = ALLOWED_SORTS.get(sortBy == null ? "hostname" : sortBy);
        if (orderClause == null) {
            throw new IllegalArgumentException("Disallowed sort column");
        }

        String placeholders = String.join(", ", Collections.nCopies(regions.size(), "?"));
        var sql = new StringBuilder(
            "SELECT hostname FROM nodes WHERE org_id = ? AND region IN (" + placeholders + ")"
        );
        boolean hasHostFilter = hostFilter != null && !hostFilter.isBlank();
        if (hasHostFilter) {
            sql.append(" AND hostname LIKE ? ESCAPE '\\'");
        }
        sql.append(" ORDER BY ").append(orderClause).append(" LIMIT 100");

        try (PreparedStatement ps = conn.prepareStatement(sql.toString())) {
            int idx = 1;
            ps.setLong(idx++, orgId);
            for (String region : regions) {
                ps.setString(idx++, region);
            }
            if (hasHostFilter) {
                ps.setString(idx++, "%" + escapeLike(hostFilter) + "%");
            }

            List<String> hosts = new ArrayList<>();
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    hosts.add(rs.getString(1));
                }
            }
            return hosts;
        }
    }
}
