package main

import (
	"bytes"
	"context"
	"crypto/tls"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"strings"
	"time"
)

const maxTailChunk = 1 << 20 // 1 MiB

func readLastNLines(rootDir, fileName string, maxLines int) ([]byte, error) {
	root, err := os.OpenRoot(rootDir)
	if err != nil {
		return nil, err
	}
	defer root.Close()

	f, err := root.Open(fileName)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	info, err := f.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, errors.New("log target is not a regular file")
	}

	size := info.Size()
	start := int64(0)
	if size > maxTailChunk {
		start = size - maxTailChunk
	}
	if _, err := f.Seek(start, io.SeekStart); err != nil {
		return nil, err
	}
	chunk, err := io.ReadAll(io.LimitReader(f, maxTailChunk))
	if err != nil {
		return nil, err
	}

	lines := bytes.Split(bytes.TrimRight(chunk, "\n"), []byte("\n"))
	if len(lines) > maxLines {
		lines = lines[len(lines)-maxLines:]
	}
	return append(bytes.Join(lines, []byte("\n")), '\n'), nil
}

func shipTail(parent context.Context, ingestURL, token string, payload []byte) error {
	if !strings.HasPrefix(ingestURL, "https://") {
		return errors.New("ingestURL must use https://")
	}
	if token == "" {
		return errors.New("SHIP_TOKEN environment variable is empty")
	}

	ctx, cancel := context.WithTimeout(parent, 10*time.Second)
	defer cancel()

	client := &http.Client{
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{MinVersion: tls.VersionTLS13},
		},
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, ingestURL, bytes.NewReader(payload))
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Content-Type", "text/plain; charset=utf-8")

	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return fmt.Errorf("ingest endpoint returned HTTP %d", resp.StatusCode)
	}
	return nil
}

func main() {
	dir := flag.String("dir", "/var/log/audit", "audit log directory")
	file := flag.String("file", "audit.log", "audit log filename")
	lines := flag.Int("lines", 200, "number of trailing lines")
	url := flag.String("url", "", "HTTPS ingest endpoint")
	flag.Parse()

	payload, err := readLastNLines(*dir, *file, *lines)
	if err != nil {
		log.Fatal(err)
	}
	if err := shipTail(context.Background(), *url, os.Getenv("SHIP_TOKEN"), payload); err != nil {
		log.Fatal(err)
	}
}
