import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

const V2_PREFIX = "v2:";
const GCM_NONCE_BYTES = 12;
const GCM_TAG_BYTES = 16;

export function encryptApiKey(key32: Buffer, ownerId: string, rawSecret: string): string {
  if (key32.byteLength !== 32) {
    throw new RangeError("AES-256-GCM requires a 32-byte key");
  }
  if (ownerId.length === 0) {
    throw new Error("ownerId AAD must be non-empty");
  }

  const nonce = randomBytes(GCM_NONCE_BYTES);
  const cipher = createCipheriv("aes-256-gcm", key32, nonce);
  cipher.setAAD(Buffer.from(`apikey:${ownerId}`, "utf8"));

  const ct = Buffer.concat([cipher.update(rawSecret, "utf8"), cipher.final()]);
  const tag = cipher.getAuthTag();
  return `${V2_PREFIX}${Buffer.concat([nonce, tag, ct]).toString("base64url")}`;
}

export function decryptApiKey(key32: Buffer, ownerId: string, stored: string): string {
  if (key32.byteLength !== 32) {
    throw new RangeError("AES-256-GCM requires a 32-byte key");
  }
  if (!stored.startsWith(V2_PREFIX)) {
    throw new Error("Unsupported or legacy unauthenticated ciphertext version");
  }

  const raw = Buffer.from(stored.slice(V2_PREFIX.length), "base64url");
  if (raw.byteLength < GCM_NONCE_BYTES + GCM_TAG_BYTES) {
    throw new Error("Truncated AES-256-GCM envelope");
  }

  const nonce = raw.subarray(0, GCM_NONCE_BYTES);
  const tag = raw.subarray(GCM_NONCE_BYTES, GCM_NONCE_BYTES + GCM_TAG_BYTES);
  const ct = raw.subarray(GCM_NONCE_BYTES + GCM_TAG_BYTES);

  const decipher = createDecipheriv("aes-256-gcm", key32, nonce);
  decipher.setAAD(Buffer.from(`apikey:${ownerId}`, "utf8"));
  decipher.setAuthTag(tag);

  const plain = Buffer.concat([decipher.update(ct), decipher.final()]);
  return plain.toString("utf8");
}
