use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};

struct BreakerState {
    consecutive_failures: u32,
    open_until: Option<Instant>,
}

#[derive(Clone)]
pub struct UpstreamBreaker {
    inner: Arc<Mutex<BreakerState>>,
    threshold: u32,
    cooldown: Duration,
}

impl UpstreamBreaker {
    pub fn new(threshold: u32, cooldown: Duration) -> Self {
        Self {
            inner: Arc::new(Mutex::new(BreakerState {
                consecutive_failures: 0,
                open_until: None,
            })),
            threshold,
            cooldown,
        }
    }

    pub fn can_probe(&self, now: Instant) -> bool {
        let guard = self.inner.lock().expect("breaker mutex poisoned");
        guard.open_until.map_or(true, |until| now >= until)
    }

    pub fn record_outcome(&self, success: bool, now: Instant) -> bool {
        let mut guard = self.inner.lock().expect("breaker mutex poisoned");
        if success {
            guard.consecutive_failures = 0;
            guard.open_until = None;
            return false;
        }
        guard.consecutive_failures = guard.consecutive_failures.saturating_add(1);
        if guard.consecutive_failures >= self.threshold {
            guard.open_until = Some(now + self.cooldown);
            return true;
        }
        false
    }
}
