#[derive(Debug, Clone, PartialEq, Eq)]
pub struct IhexRecord {
    pub address: u16,
    pub record_type: u8,
    pub data: Vec<u8>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum IhexError {
    MissingStartCode,
    InvalidLength,
    InvalidHex,
    ChecksumMismatch { computed_sum: u8 },
}

fn hex_byte(pair: &[u8]) -> Option<u8> {
    let nib = |c: u8| -> Option<u8> {
        match c {
            b'0'..=b'9' => Some(c - b'0'),
            b'a'..=b'f' => Some(c - b'a' + 10),
            b'A'..=b'F' => Some(c - b'A' + 10),
            _ => None,
        }
    };
    Some((nib(*pair.first()?)? << 4) | nib(*pair.get(1)?)?)
}

pub fn parse_ihex_line(raw_line: &str) -> Result<IhexRecord, IhexError> {
    let trimmed = raw_line.trim_end_matches(['\r', '\n']);
    let hex_body = trimmed
        .strip_prefix(':')
        .ok_or(IhexError::MissingStartCode)?
        .as_bytes();

