    if hex_body.len() < 10 || hex_body.len() % 2 != 0 {
        return Err(IhexError::InvalidLength);
    }

    let total_bytes = hex_body.len() / 2;
    let mut decoded = Vec::with_capacity(total_bytes);
    let mut sum = 0u8;
    for pair in hex_body.chunks_exact(2) {
        let b = hex_byte(pair).ok_or(IhexError::InvalidHex)?;
        sum = sum.wrapping_add(b);
        decoded.push(b);
    }

    let byte_count = decoded[0] as usize;
    if total_bytes != 4 + byte_count + 1 {
        return Err(IhexError::InvalidLength);
    }
    if sum != 0 {
        return Err(IhexError::ChecksumMismatch { computed_sum: sum });
    }

    let address = u16::from_be_bytes([decoded[1], decoded[2]]);
    let record_type = decoded[3];
    let data = decoded[4..(4 + byte_count)].to_vec();

    Ok(IhexRecord {
        address,
        record_type,
        data,
    })
}
