package main

import (
	"bufio"
	"context"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"log"
	"os"
	"os/exec"
	"regexp"
	"strings"
	"time"
)

var orgIDPattern = regexp.MustCompile(`^[a-zA-Z0-9_-]{1,64}$`)

var allowedFormats = map[string]bool{
	"pdf": true,
	"csv": true,
}

type ReportJob struct {
	OrgID  string
	Format string
}

func parseJobFile(r io.Reader) (ReportJob, error) {
	var job ReportJob
	sc := bufio.NewScanner(io.LimitReader(r, 8192))
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			return ReportJob{}, errors.New("malformed job line")
		}
		val := strings.Trim(strings.TrimSpace(v), `"'`)
		switch strings.TrimSpace(k) {
		case "ORG_ID":
			job.OrgID = val
		case "FMT":
			job.Format = val
		default:
			return ReportJob{}, fmt.Errorf("unexpected job key %q", k)
		}
	}
	if err := sc.Err(); err != nil {
		return ReportJob{}, err
	}
	if !orgIDPattern.MatchString(job.OrgID) || !allowedFormats[job.Format] {
		return ReportJob{}, errors.New("invalid ORG_ID or FMT value")
	}
	return job, nil
}

func runSpool(spoolDir string) error {
	root, err := os.OpenRoot(spoolDir)
	if err != nil {
		return err
	}
	defer root.Close()

	entries, err := fs.ReadDir(root.FS(), ".")
	if err != nil {
		return err
	}

	var errs []error
	for _, entry := range entries {
		name := entry.Name()
		if !entry.Type().IsRegular() || !strings.HasSuffix(name, ".job") {
			continue
		}
		f, err := root.Open(name)
		if err != nil {
			errs = append(errs, err)
			continue
		}
		job, parseErr := parseJobFile(f)
		_ = f.Close()
		if parseErr != nil {
			errs = append(errs, fmt.Errorf("%s: %w", name, parseErr))
			continue
		}

		ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		cmd := exec.CommandContext(ctx, "/usr/local/bin/render-report", "--org", job.OrgID, "--format", job.Format)
		runErr := cmd.Run()
		cancel()
		if runErr != nil {
			errs = append(errs, fmt.Errorf("%s exec: %w", name, runErr))
			continue
		}
		if rmErr := root.Remove(name); rmErr != nil {
			errs = append(errs, rmErr)
		}
	}
	return errors.Join(errs...)
}

func main() {
	if err := runSpool("/var/spool/reports"); err != nil {
		log.Fatal(err)
	}
}
