#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ProxyV2Header {
    Local,
    Proxied { src: SocketAddr, dst: SocketAddr },
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Pp2Error {
    NeedMoreBytes,
    BadSignature,
    UnsupportedVersionOrCmd(u8),
    UnsupportedAddressFamily(u8),
    TruncatedAddressBlock,
}

pub fn parse_proxy_v2(buf: &[u8]) -> Result<(ProxyV2Header, &[u8]), Pp2Error> {
