#include <sys/mman.h>
#include <sys/stat.h>
#include <unistd.h>
#include <utility>

class MappedFile {
public:
    MappedFile() noexcept = default;

    static std::expected<MappedFile, int> open_readonly(const std::filesystem::path& path) noexcept {
        const int fd = ::open(path.c_str(), O_RDONLY | O_CLOEXEC);
