func waitForTCP(parent context.Context, addr string, totalTimeout time.Duration) error {
	ctx, cancel := context.WithTimeout(parent, totalTimeout)
	defer cancel()

	dialer := net.Dialer{Timeout: 2 * time.Second}
	ticker := time.NewTicker(500 * time.Millisecond)
	defer ticker.Stop()

	for {
		conn, err := dialer.DialContext(ctx, "tcp", addr)
		if err == nil {
			_ = conn.Close()
			return nil
		}
		select {
		case <-ctx.Done():
			return fmt.Errorf("timed out waiting for %s: %w", addr, ctx.Err())
		case <-ticker.C:
		}
	}
}

func execTarget(argv []string) error {
	if len(argv) == 0 {
		return errors.New("missing target command after --")
	}
	binPath, err := exec.LookPath(argv[0])
	if err != nil {
		return err
	}
	return syscall.Exec(binPath, argv, os.Environ())
}

func main() {
	host := flag.String("host", os.Getenv("DB_HOST"), "TCP host")
	port := flag.String("port", os.Getenv("DB_PORT"), "TCP port")
	wait := flag.Duration("timeout", 30*time.Second, "maximum wait duration")
	flag.Parse()

	if *host == "" || *port == "" {
		log.Fatal("both host and port are required")
	}
	targetAddr := net.JoinHostPort(*host, *port)
	if err := waitForTCP(context.Background(), targetAddr, *wait); err != nil {
		log.Fatal(err)
	}
	if err := execTarget(flag.Args()); err != nil {
