        if (b & 0x80) == 0 {
            return Ok((value, &buf[(idx + 1)..]));
        }
        multiplier *= 128;
    }
    if buf.len() < 4 {
        Err(MqttSubError::Truncated)
    } else {
        Err(MqttSubError::MalformedRemainingLength)
    }
}

pub fn validate_topic_filter(filter: &str) -> Result<(), MqttSubError> {
    if filter.is_empty() || filter.contains('\0') {
        return Err(MqttSubError::InvalidTopicWildcard);
    }
    let levels: Vec<&str> = filter.split('/').collect();
    for (idx, lvl) in levels.iter().enumerate() {
        if lvl.contains('#') {
            if *lvl != "#" || idx + 1 != levels.len() {
                return Err(MqttSubError::InvalidTopicWildcard);
            }
        } else if lvl.contains('+') && *lvl != "+" {
            return Err(MqttSubError::InvalidTopicWildcard);
        }
    }
    Ok(())
}

pub fn parse_mqtt_subscribe(pkt: &[u8]) -> Result<MqttSubscribe<'_>, MqttSubError> {
    let (&first, after_first) = pkt.split_first().ok_or(MqttSubError::Truncated)?;
    if first != 0x82 {
        return Err(MqttSubError::WrongPacketType(first));
    }

    let (rem_len, rest) = decode_remaining_len(after_first)?;
    if rest.len() < rem_len {
        return Err(MqttSubError::Truncated);
    }
    let body = &rest[..rem_len];
    let (&[pid_hi, pid_lo, tlen_hi, tlen_lo], after_hdr) = body
        .split_first_chunk::<4>()
        .ok_or(MqttSubError::Truncated)?;

    let packet_id = u16::from_be_bytes([pid_hi, pid_lo]);
    let topic_len = u16::from_be_bytes([tlen_hi, tlen_lo]) as usize;
    if after_hdr.len() < topic_len + 1 {
        return Err(MqttSubError::Truncated);
    }

    let (topic_bytes, tail) = after_hdr.split_at(topic_len);
    let topic_filter = std::str::from_utf8(topic_bytes).map_err(|_| MqttSubError::InvalidTopicUtf8)?;
    validate_topic_filter(topic_filter)?;

    let qos = tail[0];
    if qos > 2 {
        return Err(MqttSubError::InvalidQos(qos));
    }

    Ok(MqttSubscribe {
        packet_id,
        topic_filter,
        qos,
    })
}
