import { EventEmitter } from "node:events";
import { z, type ZodType } from "zod";

const JobSchemas = {
  "email.send": z.object({
    to: z.string().email(),
    templateId: z.string().min(1),
  }).strict(),
  "user.deleted": z.object({
    userId: z.string().uuid(),
    purgedAtIso: z.string().datetime(),
  }).strict(),
