export class TypedJobBus {
  private readonly emitter = new EventEmitter();

  public publish<K extends JobTopic>(topic: K, payload: TopicMap[K]): boolean {
    const schema = JobSchemas[topic] as unknown as ZodType<TopicMap[K]>;
    const validated = schema.parse(payload);
    return this.emitter.emit(topic, validated);
