#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FindingSort {
    ScoreDesc,
    IdDesc,
    CategoryAsc,
}

impl FindingSort {
    pub fn from_wire(raw: &str) -> Option<Self> {
        match raw {
            "score" => Some(Self::ScoreDesc),
            "id" => Some(Self::IdDesc),
            "category" => Some(Self::CategoryAsc),
            _ => None,
        }
    }

    const fn order_sql(self) -> &'static str {
        match self {
            Self::ScoreDesc => "score DESC, id DESC",
            Self::IdDesc => "id DESC",
            Self::CategoryAsc => "category ASC, score DESC",
        }
    }
}

pub async fn search_findings(
    client: &Client,
    workspace_id: &str,
    categories: &[String],
    min_score: Option<i32>,
    sort_by: FindingSort,
) -> Result<Vec<Row>, Error> {
