    if let Some(ref ms) = min_score {
        sql.push_str(" AND score >= $3");
        params.push(ms);
    }

    sql.push_str(" ORDER BY ");
    sql.push_str(sort_by.order_sql());
    sql.push_str(" LIMIT 100");

    client.query(&sql, &params).await
}
