const maxClockSkew = 5 * time.Minute

var (
	ErrInvalidTimestamp = errors.New("invalid or expired webhook timestamp")
	ErrInvalidSignature = errors.New("webhook signature verification failed")
)

func VerifyWebhook(secret, body []byte, tsHeader, sigHex string, now time.Time) error {
	if len(secret) < 32 {
		return errors.New("webhook secret must be at least 32 bytes")
	}

	unixSec, err := strconv.ParseInt(tsHeader, 10, 64)
	if err != nil {
		return ErrInvalidTimestamp
