func reopenNginxLogs(pidPath string) error {
	fi, err := os.Lstat(pidPath)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil
		}
		return err
	}
	if !fi.Mode().IsRegular() {
		return fmt.Errorf("refusing non-regular pidfile %q", pidPath)
	}
	if st, ok := fi.Sys().(*syscall.Stat_t); ok && st.Uid != 0 {
		return fmt.Errorf("refusing pidfile %q not owned by uid 0 (uid=%d)", pidPath, st.Uid)
	}

	raw, err := os.ReadFile(pidPath)
	if err != nil {
		return err
	}
	pid, err := strconv.Atoi(strings.TrimSpace(string(raw)))
	if err != nil || pid <= 1 {
		return fmt.Errorf("invalid pid %q in %s", string(raw), pidPath)
	}

	commBytes, err := os.ReadFile(fmt.Sprintf("/proc/%d/comm", pid))
	if err != nil {
		return fmt.Errorf("read /proc/%d/comm: %w", pid, err)
	}
	if strings.TrimSpace(string(commBytes)) != "nginx" {
		return fmt.Errorf("pid %d comm mismatch (not nginx)", pid)
	}

	return syscall.Kill(pid, syscall.SIGUSR1)
}

