    TruncatedHeader,
    InvalidPacketLength(usize),
    TruncatedPacket { declared: usize, actual: usize },
    TruncatedAttrHeader { offset: usize },
    InvalidAttrLength { offset: usize, len: u8 },
    TruncatedAttrValue { offset: usize, len: usize, remaining: usize },
}

pub fn parse_radius(buf: &[u8]) -> Result<RadiusPacket<'_>, RadiusError> {
