    let mut authenticator = [0u8; 16];
    authenticator.copy_from_slice(&pkt[4..20]);

    let mut attributes = Vec::new();
    let mut offset = RADIUS_HDR_LEN;
    while offset < declared_len {
        let rem = &pkt[offset..];
        let (&[attr_type, raw_len], _) = rem
            .split_first_chunk::<2>()
            .ok_or(RadiusError::TruncatedAttrHeader { offset })?;
        if raw_len < 2 {
            return Err(RadiusError::InvalidAttrLength { offset, len: raw_len });
        }
        let total_attr = raw_len as usize;
        if rem.len() < total_attr {
            return Err(RadiusError::TruncatedAttrValue {
                offset,
                len: total_attr,
                remaining: rem.len(),
            });
        }
        attributes.push(RadiusAttr {
            attr_type,
            value: &rem[2..total_attr],
        });
        offset += total_attr;
    }

    Ok(RadiusPacket {
        code: pkt[0],
        identifier: pkt[1],
        authenticator,
