var (
	semverTagRe = regexp.MustCompile(`^v[0-9]{1,4}\.[0-9]{1,4}\.[0-9]{1,4}(-[a-zA-Z0-9.]+)?$`)
	hostNameRe  = regexp.MustCompile(`^[a-zA-Z0-9.-]{1,253}$`)
