	resolvedSrc, err := filepath.EvalSymlinks(buildDir)
	if err != nil {
		return fmt.Errorf("resolve buildDir: %w", err)
	}
	fi, err := os.Stat(resolvedSrc)
	if err != nil || !fi.IsDir() {
		return errors.New("buildDir must be an existing directory")
	}

	ctx, cancel := context.WithTimeout(parent, 5*time.Minute)
	defer cancel()

	dest := fmt.Sprintf("deploy@%s:/srv/releases/%s/", host, tag)
	cmd := exec.CommandContext(
		ctx,
		"rsync",
		"-az",
		"--delay-updates",
		"--chmod=Du=rwx,Dg=rx,Do=rx,Fu=rw,Fg=r,Fo=r",
		"--",
		resolvedSrc+"/",
		dest,
	)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func main() {
	src := flag.String("dir", "", "local build directory")
	host := flag.String("host", "", "target deploy host")
	tag := flag.String("tag", "", "release semver tag (vX.Y.Z)")
	flag.Parse()

	if err := publishRelease(context.Background(), *src, *host, *tag); err != nil {
		log.Fatal(err)
	}
}
