import bcrypt from "bcryptjs";

export type LoginVerifyOutcome =
  | { readonly valid: false }
  | { readonly valid: true; readonly upgradedHash: string | null };

const SCRYPT_PARAMS = { N: 32_768, r: 8, p: 1, maxmem: 64 * 1024 * 1024 } as const;

function deriveScryptSha512(password: string, salt: Buffer): Promise<Buffer> {
  const prehashed = createHash("sha512").update(password.normalize("NFKC"), "utf8").digest();
  return new Promise((resolve, reject) => {
