      prehashed.fill(0);
      if (err) reject(err);
      else resolve(dk);
    });
  });
}

export async function hashPasswordModern(password: string): Promise<string> {
  const salt = randomBytes(16);
  const dk = await deriveScryptSha512(password, salt);
  return `scrypt-sha512$${salt.toString("base64url")}$${dk.toString("base64url")}`;
}

export async function verifyAndUpgradeLogin(storedHash: string, password: string): Promise<LoginVerifyOutcome> {
  if (storedHash.startsWith("scrypt-sha512$")) {
    const parts = storedHash.split("$");
    if (parts.length !== 3) {
      return { valid: false };
    }
    const salt = Buffer.from(parts[1]!, "base64url");
    const expected = Buffer.from(parts[2]!, "base64url");
    if (salt.byteLength !== 16 || expected.byteLength !== 64) {
      return { valid: false };
    }
    const actual = await deriveScryptSha512(password, salt);
    const match = actual.byteLength === expected.byteLength && timingSafeEqual(actual, expected);
    return match ? { valid: true, upgradedHash: null } : { valid: false };
  }

