    // Reject >72-byte passphrases on legacy bcrypt rather than silently truncating
    if (Buffer.byteLength(password, "utf8") > 72) {
      return { valid: false };
    }
    const ok = await bcrypt.compare(password, storedHash);
    if (!ok) {
      return { valid: false };
    }
    const upgradedHash = await hashPasswordModern(password);
    return { valid: true, upgradedHash };
  }

  return { valid: false };
}
