func verifyFileInRoot(root *os.Root, relPath string, expectedDigest []byte) error {
	f, err := root.Open(relPath)
	if err != nil {
		return err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return err
