	}
	return nil
}

func verifyManifest(releaseDir, manifestName string) error {
	root, err := os.OpenRoot(releaseDir)
	if err != nil {
		return err
	}
	defer root.Close()

	mf, err := root.Open(manifestName)
	if err != nil {
		return err
	}
	defer mf.Close()

	sc := bufio.NewScanner(io.LimitReader(mf, 4<<20))
	checked := 0
	var errs []error

	for sc.Scan() {
		line := strings.TrimRight(sc.Text(), "\r\n")
		if strings.TrimSpace(line) == "" {
			continue
		}
		if len(line) < 67 || (line[64] != ' ' || (line[65] != ' ' && line[65] != '*')) {
			errs = append(errs, fmt.Errorf("malformed manifest line: %q", line))
			continue
