		if err := verifyFileInRoot(root, fileName, expected); err != nil {
			errs = append(errs, fmt.Errorf("%s: %w", fileName, err))
			continue
		}
		checked++
	}
	if err := sc.Err(); err != nil {
		errs = append(errs, err)
	}
	if checked == 0 && len(errs) == 0 {
		return errors.New("manifest contained zero entries")
	}
	return errors.Join(errs...)
}

func main() {
	dir := flag.String("dir", ".", "release directory")
	manifest := flag.String("manifest", "SHA256SUMS", "manifest filename inside dir")
	flag.Parse()

	if err := verifyManifest(*dir, *manifest); err != nil {
