    if e_phnum == 0 {
        return Ok(Elf64PhdrSlice {
            endian,
            phnum: 0,
            raw_table: &[],
        });
    }
    if usize::from(e_phentsize) != ELF64_PHDR_SIZE {
        return Err(ElfError::UnexpectedPhdrEntrySize(e_phentsize));
