    let table_end = phoff_usize
        .checked_add(table_len)
        .ok_or(ElfError::PhdrRangeOutOfBounds)?;

    let raw_table = buf
        .get(phoff_usize..table_end)
        .ok_or(ElfError::PhdrRangeOutOfBounds)?;

    Ok(Elf64PhdrSlice {
        endian,
        phnum: e_phnum,
        raw_table,
    })
