import type { NextFunction, Request, Response } from "express";
import { z } from "zod";

const RateLimitOptionsSchema = z.object({
  maxRequests: z.number().int().min(1).max(100_000),
  windowMs: z.number().int().min(1_000).max(3_600_000).default(60_000),
  maxTrackedKeys: z.number().int().min(100).max(500_000).default(50_000),
}).strict();

