  count: number;
  resetAt: number;
}

export function createRateLimiter(rawOptions: RateLimitOptions) {
  const opts = RateLimitOptionsSchema.parse(rawOptions);
  const buckets = new Map<string, WindowState>();

  const sweepExpired = (now: number): void => {
    for (const [k, state] of buckets) {
      if (state.resetAt <= now) {
        buckets.delete(k);
      }
    }
  };

  return (req: Request, res: Response, next: NextFunction): void => {
    const apiKey = req.header("x-api-key");
    const clientKey = typeof apiKey === "string" && apiKey.length > 0 && apiKey.length <= 128
