	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"os"
	"os/exec"
	"regexp"
	"time"
)

var safeDbNameRe = regexp.MustCompile(`^[a-zA-Z0-9_]{1,63}$`)

func dumpDatabase(parent context.Context, backupDir, host, user, dbName, dbPass string) error {
	if !safeDbNameRe.MatchString(dbName) {
		return fmt.Errorf("invalid database identifier %q", dbName)
	}
	if host == "" || dbPass == "" {
		return errors.New("DB_HOST and DB_PASS must be non-empty")
	}

	root, err := os.OpenRoot(backupDir)
	if err != nil {
		return err
	}
	defer root.Close()

	tmpName := dbName + ".sql.gz.tmp"
	finalName := dbName + ".sql.gz"
	outFile, err := root.OpenFile(tmpName, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o600)
	if err != nil {
		return err
	}

	ctx, cancel := context.WithTimeout(parent, 30*time.Minute)
	defer cancel()

	cmd := exec.CommandContext(
		ctx,
		"pg_dump",
		"--no-password",
		"--host="+host,
		"--username="+user,
		"--dbname="+dbName,
	)
	cmd.Env = append(os.Environ(), "PGPASSWORD="+dbPass)
	cmd.Stderr = os.Stderr

	stdoutPipe, err := cmd.StdoutPipe()
	if err != nil {
		_ = outFile.Close()
		_ = root.Remove(tmpName)
		return err
	}
	if err := cmd.Start(); err != nil {
		_ = outFile.Close()
		_ = root.Remove(tmpName)
		return err
	}

	gz := gzip.NewWriter(outFile)
	_, copyErr := io.Copy(gz, stdoutPipe)
	gzErr := gz.Close()
	waitErr := cmd.Wait()
	syncErr := outFile.Sync()
	closeErr := outFile.Close()

	if err := errors.Join(copyErr, gzErr, waitErr, syncErr, closeErr); err != nil {
		_ = root.Remove(tmpName)
		return fmt.Errorf("pg_dump backup failed: %w", err)
	}
	return root.Rename(tmpName, finalName)
}

func main() {
	dir := flag.String("dir", "/srv/backups", "backup root directory")
	db := flag.String("db", "", "PostgreSQL database name")
	user := flag.String("user", "backup_ro", "PostgreSQL role")
	flag.Parse()

	if err := dumpDatabase(
		context.Background(),
		*dir,
		os.Getenv("DB_HOST"),
		*user,
		*db,
		os.Getenv("DB_PASS"),
	); err != nil {
		log.Fatal(err)
