        .split_once([' ', '\t'])
        .ok_or(AuthKeyError::MissingFields)?;
    let key_type = SshKeyType::parse(raw_type).ok_or(AuthKeyError::UnsupportedKeyType)?;

    let rest = rest.trim_start_matches([' ', '\t']);
    if rest.is_empty() {
        return Err(AuthKeyError::MissingFields);
    }

    let (blob, comment) = match rest.split_once([' ', '\t']) {
        Some((b, c)) => {
            let clean_c = c.trim();
            (b, (!clean_c.is_empty()).then_some(clean_c))
        }
        None => (rest, None),
    };

    if !is_valid_standard_b64(blob) {
        return Err(AuthKeyError::InvalidBase64Blob);
    }

    Ok(Some(AuthorizedKey {
        key_type,
        base64_blob: blob,
        comment,
    }))
