var (
	unitNameRe = regexp.MustCompile(`^[a-zA-Z0-9@_.-]{1,64}$`)
	envKeyRe   = regexp.MustCompile(`^[A-Z_][A-Z0-9_]{0,63}$`)
)

func escapeSystemdValue(v string) (string, error) {
	for _, r := range v {
		if r < 0x20 || r == 0x7f {
			return "", errors.New("control characters and newlines are disallowed in Environment values")
		}
	}
	replacer := strings.NewReplacer(`\`, `\\`, `"`, `\"`, `%`, `%%`)
	return replacer.Replace(v), nil
}

func writeUnitEnvDropIn(parent context.Context, baseSystemdDir, svc, key, val string) error {
	if !unitNameRe.MatchString(svc) || strings.Contains(svc, "..") {
		return fmt.Errorf("invalid service name %q", svc)
	}
	if !envKeyRe.MatchString(key) {
		return fmt.Errorf("invalid environment variable name %q", key)
	}
	escapedVal, err := escapeSystemdValue(val)
	if err != nil {
		return err
	}

	dropInDir := filepath.Join(baseSystemdDir, svc+".service.d")
	if err := os.MkdirAll(dropInDir, 0o755); err != nil {
		return err
	}

	content := fmt.Sprintf("[Service]\nEnvironment=\"%s=%s\"\n", key, escapedVal)
	tmp, err := os.CreateTemp(dropInDir, ".override.conf.tmp.*")
	if err != nil {
		return err
	}
	tmpName := tmp.Name()
	cleanup := true
	defer func() {
		if cleanup {
			_ = os.Remove(tmpName)
		}
	}()

	if err := tmp.Chmod(0o644); err != nil {
		_ = tmp.Close()
		return err
	}
	if _, err := tmp.WriteString(content); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}

	if err := os.Rename(tmpName, filepath.Join(dropInDir, "override.conf")); err != nil {
		return err
	}
	cleanup = false

	ctx, cancel := context.WithTimeout(parent, 15*time.Second)
	defer cancel()
	return exec.CommandContext(ctx, "systemctl", "daemon-reload").Run()
}

func main() {
