import type { ZodType } from "zod";

export interface RetryFetchOptions {
  maxAttempts?: number;
  baseDelayMs?: number;
  maxDelayMs?: number;
  perAttemptTimeoutMs?: number;
  signal?: AbortSignal;
}

class NonRetryableHttpError extends Error {
  constructor(public readonly status: number) {
    super(`Non-retryable HTTP status ${status}`);
    this.name = "NonRetryableHttpError";
  }
}

function isRetryableStatus(status: number): boolean {
  return status === 408 || status === 429 || (status >= 500 && status <= 599);
}

function sleepWithAbort(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
      return;
    }
    const timer = setTimeout(() => {
      signal?.removeEventListener("abort", onAbort);
      resolve();
    }, ms);
    const onAbort = (): void => {
      clearTimeout(timer);
      reject(signal?.reason ?? new DOMException("Aborted", "AbortError"));
    };
    signal?.addEventListener("abort", onAbort, { once: true });
  });
}

export async function fetchValidatedWithRetry<T>(
  url: string,
  schema: ZodType<T>,
  opts: RetryFetchOptions = {},
): Promise<T> {
  const maxAttempts = Math.max(1, Math.min(opts.maxAttempts ?? 3, 8));
  const baseDelayMs = opts.baseDelayMs ?? 250;
  const maxDelayMs = opts.maxDelayMs ?? 5_000;
  const timeoutMs = opts.perAttemptTimeoutMs ?? 4_000;

  let lastErr: unknown;

  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    const attemptSignal = opts.signal
      ? AbortSignal.any([opts.signal, AbortSignal.timeout(timeoutMs)])
      : AbortSignal.timeout(timeoutMs);

    try {
      const resp = await fetch(url, {
        headers: { Accept: "application/json" },
        redirect: "error",
        signal: attemptSignal,
      });

      if (!resp.ok) {
        if (!isRetryableStatus(resp.status)) {
          throw new NonRetryableHttpError(resp.status);
        }
        throw new Error(`Transient HTTP status ${resp.status}`);
      }

      const rawData: unknown = await resp.json();
      return schema.parse(rawData);
    } catch (err) {
      lastErr = err;
      if (err instanceof NonRetryableHttpError || opts.signal?.aborted || attempt === maxAttempts) {
        throw err;
      }
      const cap = Math.min(maxDelayMs, baseDelayMs * 2 ** (attempt - 1));
      const jitteredMs = Math.floor(Math.random() * cap);
      await sleepWithAbort(jitteredMs, opts.signal);
    }
  }

  throw lastErr;
}
