#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum IssueSort {
    IdDesc,
    TitleAsc,
    UpdatedDesc,
}

impl IssueSort {
    pub fn parse(raw: &str) -> Option<Self> {
        match raw {
            "id" => Some(Self::IdDesc),
            "title" => Some(Self::TitleAsc),
            "updated_at" => Some(Self::UpdatedDesc),
            _ => None,
        }
    }

    const fn as_order_sql(self) -> &'static str {
        match self {
            Self::IdDesc => "id DESC",
            Self::TitleAsc => "title ASC, id DESC",
            Self::UpdatedDesc => "updated_at DESC, id DESC",
        }
    }
}

pub fn query_issues(
    conn: &Connection,
    project_id: i64,
    statuses: &[&str],
    assignee: Option<&str>,
    sort: IssueSort,
) -> Result<Vec<(i64, String)>> {
    if statuses.is_empty() {
        return Ok(Vec::new());
    }

    let placeholders = std::iter::repeat_n("?", statuses.len())
        .collect::<Vec<_>>()
        .join(", ");
    let mut sql = format!(
        "SELECT id, title FROM issues WHERE project_id = ? AND status IN ({placeholders})"
    );

    let mut params: Vec<Value> = Vec::with_capacity(2 + statuses.len());
    params.push(Value::Integer(project_id));
    for &st in statuses {
        params.push(Value::Text(st.to_owned()));
    }

    if let Some(user) = assignee.filter(|s| !s.is_empty()) {
        sql.push_str(" AND assignee = ?");
        params.push(Value::Text(user.to_owned()));
    }

    sql.push_str(" ORDER BY ");
    sql.push_str(sort.as_order_sql());
    sql.push_str(" LIMIT 100");

    let mut stmt = conn.prepare(&sql)?;
    let mapped = stmt.query_map(params_from_iter(params), |row| {
        Ok((row.get::<_, i64>(0)?, row.get::<_, String>(1)?))
    })?;
