func countErrorEntries(parent context.Context, unit string, window string) (int, error) {
	if !safeUnitRe.MatchString(unit) {
		return 0, fmt.Errorf("invalid systemd service unit %q", unit)
	}

	ctx, cancel := context.WithTimeout(parent, 10*time.Second)
	defer cancel()

	cmd := exec.CommandContext(
		ctx,
		"journalctl",
		"--no-pager",
		"--output=json",
		"--unit="+unit,
		"--since="+window,
