        "created_at", "created_at DESC, id DESC",
        "event_type", "event_type ASC, created_at DESC",
        "actor_email", "actor_email ASC, created_at DESC",
        "id", "id DESC"
    );

    private final NamedParameterJdbcTemplate jdbc;

    public AuditTrailQueryService(NamedParameterJdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<AuditRow> getAuditPage(
        String tenantId,
        Set<String> eventTypes,
        String actorEmail,
        String sortField,
        int limit,
        int offset
    ) {
        if (eventTypes == null || eventTypes.isEmpty()) {
            return List.of();
        }
        if (limit < 1 || limit > 200 || offset < 0 || offset > 50_000) {
            throw new IllegalArgumentException("Pagination parameters out of allowed bounds");
        }
        String orderClause = ALLOWED_SORTS.get(sortField == null ? "created_at" : sortField);
        if (orderClause == null) {
            throw new IllegalArgumentException("Unsupported sort field");
        }

        var sql = new StringBuilder(
            "SELECT id, actor_email, event_type, created_at FROM audit_trail " +
            "WHERE tenant_id = :tenantId AND event_type IN (:eventTypes)"
        );
        var params = new MapSqlParameterSource()
            .addValue("tenantId", tenantId)
            .addValue("eventTypes", eventTypes)
            .addValue("limit", limit)
            .addValue("offset", offset);

        if (actorEmail != null && !actorEmail.isBlank()) {
            sql.append(" AND actor_email = :actorEmail");
            params.addValue("actorEmail", actorEmail);
        }

        sql.append(" ORDER BY ").append(orderClause).append(" LIMIT :limit OFFSET :offset");

        return jdbc.query(
            sql.toString(),
            params,
            (rs, rowNum) -> new AuditRow(
                rs.getLong("id"),
                rs.getString("actor_email"),
                rs.getString("event_type"),
                rs.getTimestamp("created_at").toInstant()
            )
        );
    }
}
