package main

import (
	"bufio"
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"flag"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"os"
	"path"
	"regexp"
	"strings"
	"sync"
	"time"
)

const maxDownloadBytes = 64 << 20 // 64 MiB

var safeFileChars = regexp.MustCompile(`[^a-zA-Z0-9._-]+`)

func safeOutputName(rawURL string) (string, error) {
	u, err := url.Parse(rawURL)
	if err != nil || u.Scheme != "https" || u.Host == "" {
		return "", fmt.Errorf("disallowed non-HTTPS URL %q", rawURL)
	}
	base := path.Base(u.Path)
	cleanBase := strings.TrimLeft(safeFileChars.ReplaceAllString(base, "_"), ".-")
	if cleanBase == "" || cleanBase == "_" {
		cleanBase = "artifact.bin"
	}
	if len(cleanBase) > 80 {
		cleanBase = cleanBase[len(cleanBase)-80:]
	}
	sum := sha256.Sum256([]byte(rawURL))
	return hex.EncodeToString(sum[:6]) + "_" + cleanBase, nil
}

func downloadOne(parent context.Context, root *os.Root, rawURL string) error {
	outName, err := safeOutputName(rawURL)
	if err != nil {
		return err
	}

	ctx, cancel := context.WithTimeout(parent, 30*time.Second)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, rawURL, nil)
	if err != nil {
		return err
	}
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("HTTP %d for %s", resp.StatusCode, rawURL)
	}

	tmpName := "." + outName + ".tmp"
	f, err := root.OpenFile(tmpName, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
	if err != nil {
		return err
	}

	n, copyErr := io.Copy(f, io.LimitReader(resp.Body, maxDownloadBytes+1))
	syncErr := f.Sync()
	closeErr := f.Close()
	if err := errors.Join(copyErr, syncErr, closeErr); err != nil {
		_ = root.Remove(tmpName)
		return err
	}
	if n > maxDownloadBytes {
		_ = root.Remove(tmpName)
		return fmt.Errorf("%s exceeded max size", rawURL)
	}
	return root.Rename(tmpName, outName)
}

func main() {
	listFile := flag.String("list", "", "path to newline-delimited HTTPS URLs")
	destDir := flag.String("dest", "/srv/mirror", "destination mirror directory")
	workers := flag.Int("workers", 8, "max concurrent downloads")
	flag.Parse()

	in, err := os.Open(*listFile)
	if err != nil {
		log.Fatal(err)
	}
	defer in.Close()

	if err := os.MkdirAll(*destDir, 0o755); err != nil {
		log.Fatal(err)
	}
	root, err := os.OpenRoot(*destDir)
	if err != nil {
		log.Fatal(err)
	}
	defer root.Close()

	var urls []string
	sc := bufio.NewScanner(in)
	for sc.Scan() {
		if u := strings.TrimSpace(sc.Text()); u != "" && !strings.HasPrefix(u, "#") {
			urls = append(urls, u)
		}
	}
	if err := sc.Err(); err != nil {
		log.Fatal(err)
	}

	sem := make(chan struct{}, max(1, min(*workers, 32)))
	var wg sync.WaitGroup
	var mu sync.Mutex
	var errs []error

	for _, targetURL := range urls {
		wg.Add(1)
		go func(u string) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			if err := downloadOne(context.Background(), root, u); err != nil {
				mu.Lock()
				errs = append(errs, err)
				mu.Unlock()
			}
		}(targetURL)
	}
	wg.Wait()
	if err := errors.Join(errs...); err != nil {
		log.Fatal(err)
	}
}
