pub fn unwrap_dek_oaep(
    priv_key: &RsaPrivateKey,
    wrapped: &[u8],
    context_label: &str,
) -> Result<Zeroizing<[u8; DEK_LEN]>, KeyWrapError> {
    if priv_key.size() * 8 < MIN_RSA_BITS {
        return Err(KeyWrapError::WeakRsaModulus);
    }
    let padding = Oaep::new_with_label::<Sha256, _>(context_label);
